CREATE INDEX "chat_deliveries_pair_seed_idx" ON "chat_deliveries" USING btree ("id") WHERE "chat_deliveries"."normalized_event" ? 'githubPairingSeed';--> statement-breakpoint
CREATE INDEX "chat_deliveries_pair_round_idx" ON "chat_deliveries" USING btree ("endpoint_id",(coalesce("normalized_event"->'githubPairingSeed'->'envelope'->'event'->>'repositoryId', "normalized_event"->'githubPairingSeed'->'envelope'->'unavailableEvent'->>'repositoryId')),(coalesce("normalized_event"->'githubPairingSeed'->'envelope'->'event'->>'pullNumber', "normalized_event"->'githubPairingSeed'->'envelope'->'unavailableEvent'->>'pullNumber')),(("normalized_event"->'githubPairingSeed'->>'roundOrdinal')::integer)) WHERE "chat_deliveries"."normalized_event" ? 'githubPairingSeed';